{/* Inbox Email Banner — shown whenever user has an inbox email */}
{user && profile?.inbox_email && (
  <div className="rounded-xl border border-primary/20 bg-gradient-to-r from-primary/5 to-transparent px-4 py-3 flex items-center gap-3 flex-wrap">
    <div className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
      <Mail className="h-4 w-4 text-primary" />
    </div>
    <div className="flex-1 min-w-0">
      <div className="flex items-center gap-2 flex-wrap">
        <p className="text-xs font-semibold text-foreground">Resume Inbox</p>
        {isExistingJob && (selectedJob as any)?.inbox_email ? (
          <Badge variant="outline" className="text-[10px] px-1.5 py-0 border-primary/30 text-primary">Job-specific</Badge>
        ) : (
          <Badge variant="outline" className="text-[10px] px-1.5 py-0">Universal</Badge>
        )}
      </div>
      <p className="text-[11px] text-muted-foreground mt-0.5">
        {isExistingJob && (selectedJob as any)?.inbox_email
          ? "Forward resumes directly to this job — they'll be auto-collected"
          : "Forward any resume to this address — it auto-routes to your active job"}
      </p>
    </div>
    <div className="flex items-center gap-2 shrink-0">
      <code className="text-xs bg-muted rounded px-2 py-1 font-mono truncate max-w-[200px] hidden sm:block">
        {isExistingJob && (selectedJob as any)?.inbox_email
          ? (selectedJob as any).inbox_email
          : profile.inbox_email}
      </code>
      <Button
        variant="outline"
        size="sm"
        className="gap-1.5 h-7 text-xs"
        onClick={() => {
          const email = isExistingJob && (selectedJob as any)?.inbox_email
            ? (selectedJob as any).inbox_email
            : profile.inbox_email!;
          navigator.clipboard.writeText(email);
          toast.success("Inbox email copied!");
        }}
      >
        <Copy className="h-3 w-3" />
        Copy
      </Button>
    </div>
  </div>
)}

{/* Two-column: JD + Upload */}
<div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:items-stretch">
  {/* Job Description */}
  <Card className="flex flex-col">
    <CardHeader className="pb-3">
      <div className="flex items-center justify-between">
        <CardTitle className="text-lg">
          {isExistingJob ? "Job Description" : "Paste Job Description"}
        </CardTitle>
        {isExistingJob && selectedJob?.jd_analysis_json && (
          <Badge variant="secondary" className="gap-1 text-[10px]">
            <Zap className="h-2.5 w-2.5 text-primary" />
            AI analyzed
          </Badge>
        )}
      </div>
    </CardHeader>
    <CardContent className="flex-1 flex flex-col">
      {isExistingJob ? (
        <div className="bg-muted/50 rounded-md p-4 text-sm whitespace-pre-wrap flex-1 max-h-[300px] overflow-auto">
          {selectedJob?.job_description}
        </div>
      ) : (
        <Textarea
          placeholder="Paste the full job description here…"
          value={jobDescription}
          onFocus={() => { if (!isAuthenticated) { onAuthRequired(); } }}
          onChange={(e) => { if (!isAuthenticated) { onAuthRequired(); return; } setJobDescription(e.target.value); }}
          className="min-h-[200px] flex-1 resize-y"
        />
      )}
    </CardContent>
  </Card>

  {/* Upload Resumes */}
  <Card className="flex flex-col">
    <CardHeader className="pb-3">
      <div className="flex items-center justify-between">
        <CardTitle className="text-lg">
          {isExistingJob ? "Add More Resumes" : "Upload Resumes"}
        </CardTitle>
        {isExistingJob && existingResumes.length > 0 && (
          <Badge variant="secondary" className="text-[10px]">
            {existingResumes.length} uploaded
          </Badge>
        )}
      </div>
    </CardHeader>
    <CardContent className="flex-1 flex flex-col space-y-4">
      <div
        className={`border-2 border-dashed rounded-lg p-8 text-center cursor-pointer transition-all duration-300 flex flex-col items-center justify-center flex-1 ${
          dragOver ? "border-primary bg-primary/5 scale-[1.01]" : "border-border hover:border-primary/50 hover:bg-primary/[0.02]"
        }`}
        onDragOver={(e) => { e.preventDefault(); if (!isAuthenticated) return; setDragOver(true); }}
        onDragLeave={() => setDragOver(false)}
        onDrop={(e) => { if (!isAuthenticated) { e.preventDefault(); onAuthRequired(); return; } handleFileDrop(e); }}
        onClick={() => { if (!isAuthenticated) { onAuthRequired(); return; } document.getElementById("file-input")?.click(); }}
      >
        <div className="w-10 h-10 rounded-lg bg-primary/10 flex items-center justify-center mb-3">
          <Upload className="h-5 w-5 text-primary" />
        </div>
        <p className="text-sm font-medium text-foreground mb-1">Drop resumes here</p>
        <p className="text-xs text-muted-foreground">PDF or DOCX · Max {maxResumes} files · {maxFileSizeMb}MB each</p>
        <input id="file-input" type="file" className="hidden" multiple accept=".pdf,.docx" onChange={handleFileSelect} />
      </div>
      {files.length > 0 && (
        <div className="space-y-2">
          {files.map((f, i) => {
            const isProcessing = rankingFilesRef.current.has(f.name) && ranking;
            return (
              <div key={i} className="flex items-center justify-between bg-secondary/50 rounded-md px-3 py-2 animate-fade-in">
                <div className="flex items-center gap-2 text-sm">
                  {isProcessing ? <Loader2 className="h-4 w-4 text-primary animate-spin" /> : <FileText className="h-4 w-4 text-muted-foreground" />}
                  <span className={isProcessing ? "text-muted-foreground" : ""}>{f.name}</span>
                  {!isProcessing && ranking && <Badge variant="outline" className="text-xs">Queued</Badge>}
                </div>
                {!isProcessing && (
                  <Button variant="ghost" size="icon" className="h-6 w-6" onClick={() => removeFile(i)}>
                    <X className="h-3.5 w-3.5" />
                  </Button>
                )}
              </div>
            );
          })}
        </div>
      )}

      {/* Inline Inbox Email for existing jobs */}
      {isExistingJob && (selectedJob as any)?.inbox_email && (
        <div className="rounded-lg border border-dashed border-primary/30 bg-primary/5 px-3 py-2.5 flex items-center gap-2.5">
          <Mail className="h-3.5 w-3.5 text-primary shrink-0" />
          <div className="flex-1 min-w-0">
            <p className="text-[10px] font-semibold text-primary uppercase tracking-wide mb-0.5">Or email directly</p>
            <code className="text-[10px] font-mono text-muted-foreground truncate block">{(selectedJob as any).inbox_email}</code>
          </div>
        </div>
      )}
      {!isExistingJob && user && profile?.inbox_email && (
        <div className="rounded-lg border border-dashed border-primary/30 bg-primary/5 px-3 py-2.5 flex items-center gap-2.5">
          <Mail className="h-3.5 w-3.5 text-primary shrink-0" />
          <div className="flex-1 min-w-0">
            <p className="text-[10px] font-semibold text-primary uppercase tracking-wide mb-0.5">Or email directly</p>
            <code className="text-[10px] font-mono text-muted-foreground truncate block">{profile.inbox_email}</code>
          </div>
        </div>
      )}
    </CardContent>
  </Card>
</div>

