 15→
 16→  const { data: logs = [] } = useQuery({
 17→    queryKey: ["email_ingest_logs", statusFilter],
 18→    queryFn: async () => {
 19→      let query = supabase
 20→        .from("email_ingest_logs")
 21→        .select("*")
 22→        .order("created_at", { ascending: false })
 23→        .limit(100);
 24→
 25→      if (statusFilter !== "all") {
 26→        query = query.eq("status", statusFilter);
 27→      }
 28→
 29→      const { data, error } = await query;
 30→      if (error) throw error;
 31→      return data as Array<{
 32→        id: string;
 33→        created_at: string;
 34→        sender: string | null;
 35→        recipient: string | null;
 36→        user_id: string | null;
 37→        job_id: string | null;
 38→        status: string;
 39→        error_message: string | null;
 40→        attachments_count: number;
 41→        resumes_created: number;
 42→      }>;
 43→    },
 44→    refetchInterval: 30000,
 45→  });
 46→
 47→  const filtered = logs.filter(
 48→    (l) =>
 49→      !search ||
 50→      l.sender?.toLowerCase().includes(search.toLowerCase()) ||
 51→      l.recipient?.toLowerCase().includes(search.toLowerCase()) ||
 52→      l.error_message?.toLowerCase().includes(search.toLowerCase())
