 80→            <Input
 81→              placeholder="Search by sender or error..."
 82→              value={search}
 83→              onChange={(e) => setSearch(e.target.value)}
 84→              className="pl-9"
 85→            />
 86→          </div>
 87→          <Select value={statusFilter} onValueChange={setStatusFilter}>
 88→            <SelectTrigger className="w-[130px]">
 89→              <SelectValue placeholder="Status" />
 90→            </SelectTrigger>
 91→            <SelectContent>
