 93→              <SelectItem value="success">Success</SelectItem>
 94→              <SelectItem value="rejected">Rejected</SelectItem>
 95→              <SelectItem value="error">Error</SelectItem>
 96→            </SelectContent>
 97→          </Select>
 98→        </div>
 99→
100→        <div className="rounded-md border">
101→          <Table>
102→            <TableHeader>
103→              <TableRow>
104→                <TableHead>Time</TableHead>
105→                <TableHead>Sender</TableHead>
106→                <TableHead>Recipient</TableHead>
107→                <TableHead>Status</TableHead>
108→                <TableHead className="text-right">Files</TableHead>
109→                <TableHead>Error</TableHead>
110→              </TableRow>
111→            </TableHeader>
