119→              ) : (
120→                filtered.map((log) => (
121→                  <TableRow key={log.id}>
122→                    <TableCell className="text-xs text-muted-foreground whitespace-nowrap">
123→                      {format(new Date(log.created_at), "MMM d, HH:mm")}
124→                    </TableCell>
