 35→serve(async (req) => {
 36→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 37→
 38→  try {
 39→    const { supabase, adminUserId } = await authenticateAdmin(req);
 40→
 41→    let body: any = null;
 42→    try {
 43→      const text = await req.text();
 44→      if (text) body = JSON.parse(text);
 45→    } catch {
 46→      // empty or invalid body — treat as list request
 47→    }
 48→
 49→    const action = body?.action;
 50→
 51→    // ─── Ban / Suspend user ───
 52→    if (action === "ban") {
 53→      const { user_id, banned } = body;
 54→      if (!user_id) throw new Error("user_id required");
 55→      if (banned) {
 56→        const { error } = await supabase.auth.admin.updateUserById(user_id, { ban_duration: "876000h" }); // ~100 years
 57→        if (error) throw error;
 58→      } else {
 59→        const { error } = await supabase.auth.admin.updateUserById(user_id, { ban_duration: "none" });
 60→        if (error) throw error;
 61→      }
 62→      return new Response(JSON.stringify({ success: true }), {
 63→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 64→      });
 65→    }
 66→
 67→    // ─── Get user activity detail ───
 68→    if (action === "activity") {
 69→      const { user_id } = body;
 70→      if (!user_id) throw new Error("user_id required");
 71→
 72→      const [usageRes, jobsRes, resumesRes, paymentsRes] = await Promise.all([
 73→        supabase.from("usage_logs").select("*").eq("user_id", user_id).order("created_at", { ascending: false }).limit(50),
 74→        supabase.from("jobs").select("id, title, status, created_at").eq("user_id", user_id).order("created_at", { ascending: false }).limit(50),
 75→        supabase.from("resumes").select("id, filename, status, created_at, job_id").order("created_at", { ascending: false }).limit(100),
 76→        supabase.from("payments").select("id, amount, currency, status, credits_purchased, created_at").eq("user_id", user_id).order("created_at", { ascending: false }).limit(50),
 77→      ]);
 78→
 79→      // Filter resumes to only those belonging to user's jobs
 80→      const jobIds = new Set(jobsRes.data?.map((j: any) => j.id) ?? []);
 81→      const userResumes = resumesRes.data?.filter((r: any) => jobIds.has(r.job_id)) ?? [];
 82→
 83→      return new Response(JSON.stringify({
 84→        usage_logs: usageRes.data ?? [],
 85→        jobs: jobsRes.data ?? [],
 86→        resumes: userResumes,
 87→        payments: paymentsRes.data ?? [],
 88→      }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
 89→    }
 90→
 91→    // ─── GDPR data export ───
 92→    if (action === "gdpr_export") {
 93→      const { user_id } = body;
 94→      if (!user_id) throw new Error("user_id required");
 95→
 96→      const { data: authUser } = await supabase.auth.admin.getUserById(user_id);
 97→      const [profileRes, usageRes, jobsRes, paymentsRes, rolesRes] = await Promise.all([
 98→        supabase.from("profiles").select("*").eq("user_id", user_id),
 99→        supabase.from("usage_logs").select("*").eq("user_id", user_id),
100→        supabase.from("jobs").select("*").eq("user_id", user_id),
101→        supabase.from("payments").select("*").eq("user_id", user_id),
102→        supabase.from("user_roles").select("*").eq("user_id", user_id),
103→      ]);
104→
105→      // Get resumes for user's jobs
106→      const jobIds = jobsRes.data?.map((j: any) => j.id) ?? [];
107→      let resumes: any[] = [];
108→      if (jobIds.length > 0) {
109→        const { data } = await supabase.from("resumes").select("id, filename, status, created_at, candidate_name, source").in("job_id", jobIds);
110→        resumes = data ?? [];
111→      }
112→
113→      const exportData = {
114→        exported_at: new Date().toISOString(),
115→        user: {
116→          id: authUser?.user?.id,
117→          email: authUser?.user?.email,
118→          created_at: authUser?.user?.created_at,
119→          last_sign_in_at: authUser?.user?.last_sign_in_at,
120→        },
121→        profile: profileRes.data?.[0] ?? null,
122→        roles: rolesRes.data ?? [],
123→        jobs: jobsRes.data ?? [],
124→        resumes,
125→        usage_logs: usageRes.data ?? [],
126→        payments: paymentsRes.data ?? [],
127→      };
128→
129→      return new Response(JSON.stringify(exportData), {
130→        headers: { ...corsHeaders, "Content-Type": "application/json" },
131→      });
132→    }
133→
134→    // ─── Update user profile (existing) ───
135→    if (body && body.user_id && !action) {
136→      const { user_id, credits, plan, email_enabled } = body;
137→      const updates: any = {};
138→      if (credits !== undefined) updates.credits = credits;
139→      if (plan !== undefined) updates.plan = plan;
140→      if (email_enabled !== undefined) updates.email_enabled = email_enabled;
141→
142→      const { error } = await supabase.from("profiles").update(updates).eq("user_id", user_id);
143→      if (error) throw error;
144→
145→      return new Response(JSON.stringify({ success: true }), {
146→        headers: { ...corsHeaders, "Content-Type": "application/json" },
147→      });
148→    }
149→
150→    // ─── Update platform config (email settings etc.) ───
151→    if (action === "update_config") {
152→      const allowedFields = [
153→        "email_ingestion_enabled",
154→        "outbound_email_enabled",
155→        "sendgrid_api_key",
156→        "email_from_address",
157→        "email_from_name",
158→        "email_notify_ranking_complete",
159→        "email_notify_resume_received",
160→        "max_file_size_mb",
161→        "max_resumes_per_job",
162→        "payg_per_resume_cost",
163→        "resume_retention_days",
164→      ];
165→
166→      const updates = body.updates || {};
167→      const setClauses: string[] = [];
168→      const values: any[] = [];
169→      let paramIdx = 1;
170→
171→      for (const [key, val] of Object.entries(updates)) {
172→        if (allowedFields.includes(key)) {
173→          setClauses.push(`${key} = $${paramIdx}`);
174→          values.push(val);
175→          paramIdx++;
176→        }
177→      }
178→
179→      if (setClauses.length === 0) throw new Error("No valid fields to update");
180→
181→      setClauses.push(`updated_at = now()`);
182→      const sql = `UPDATE platform_config SET ${setClauses.join(", ")} WHERE id = (SELECT id FROM platform_config LIMIT 1)`;
183→
184→      const { error } = await supabase.rpc("exec_sql", { query: sql, params: values }).maybeSingle();
185→
186→      // Fallback: if exec_sql RPC doesn't exist, use direct update
187→      if (error) {
188→        // Try direct update via service role (bypasses PostgREST cache for service role)
189→        const { data: configRow } = await supabase.from("platform_config").select("id").limit(1).single();
190→        if (!configRow) throw new Error("No platform_config row found");
191→
192→        const cleanUpdates: any = {};
193→        for (const [key, val] of Object.entries(updates)) {
194→          if (allowedFields.includes(key)) cleanUpdates[key] = val;
195→        }
196→
197→        const { error: updateErr } = await supabase.from("platform_config").update(cleanUpdates).eq("id", configRow.id);
198→        if (updateErr) throw updateErr;
199→      }
200→
201→      return new Response(JSON.stringify({ success: true }), {
202→        headers: { ...corsHeaders, "Content-Type": "application/json" },
203→      });
204→    }
205→
206→    // ─── Get platform config ───
207→    if (action === "get_config") {
208→      const { data, error } = await supabase.from("platform_config").select("*").limit(1).single();
209→      if (error) throw error;
210→      // Mask the SendGrid API key for security
211→      if (data && (data as any).sendgrid_api_key) {
212→        const key = (data as any).sendgrid_api_key as string;
213→        (data as any).sendgrid_api_key_masked = key.slice(0, 5) + "***" + key.slice(-4);
214→        (data as any).has_sendgrid_key = true;
215→        delete (data as any).sendgrid_api_key;
216→      } else {
217→        (data as any).has_sendgrid_key = false;
218→      }
219→      return new Response(JSON.stringify(data), {
220→        headers: { ...corsHeaders, "Content-Type": "application/json" },
221→      });
222→    }
223→
224→    // ─── Get email templates ───
225→    if (action === "get_templates") {
226→      const { data, error } = await supabase
227→        .from("email_templates")
228→        .select("*")
229→        .order("template_key");
230→      if (error) throw error;
231→      return new Response(JSON.stringify(data), {
232→        headers: { ...corsHeaders, "Content-Type": "application/json" },
233→      });
234→    }
235→
236→    // ─── Update email template ───
237→    if (action === "update_template") {
238→      const { template_id, subject, body_html } = body;
239→      if (!template_id) throw new Error("template_id required");
240→      const { error } = await supabase
241→        .from("email_templates")
242→        .update({ subject, body_html, updated_at: new Date().toISOString() })
243→        .eq("id", template_id);
244→      if (error) throw error;
245→      return new Response(JSON.stringify({ success: true }), {
246→        headers: { ...corsHeaders, "Content-Type": "application/json" },
247→      });
248→    }
249→
250→    // ─── List all users (default) ───
251→    const { data: authUsers } = await supabase.auth.admin.listUsers({ perPage: 1000 });
252→    const { data: profiles } = await supabase.from("profiles").select("*");
253→    const { data: userRoles } = await supabase.from("user_roles").select("*");
254→
255→    const users = authUsers?.users?.map((u: any) => {
256→      const profile = profiles?.find((p: any) => p.user_id === u.id);
257→      const role = userRoles?.find((r: any) => r.user_id === u.id);
258→      return {
259→        id: u.id,
260→        email: u.email,
261→        credits: profile?.credits ?? 0,
262→        plan: profile?.plan ?? "free",
263→        role: role?.role ?? "user",
264→        inbox_email: profile?.inbox_email ?? null,
265→        email_enabled: profile?.email_enabled ?? true,
266→        created_at: u.created_at,
267→        last_sign_in_at: u.last_sign_in_at ?? null,
268→        banned_until: u.banned_until ?? null,
269→      };
270→    }) ?? [];
271→
272→    return new Response(JSON.stringify(users), {
273→      headers: { ...corsHeaders, "Content-Type": "application/json" },
274→    });
275→  } catch (err: unknown) {
276→    const msg = err instanceof Error ? err.message : String(err);
277→    const status = msg === "Admin access required" ? 403 : 500;
278→    return new Response(JSON.stringify({ error: msg }), {
279→      status, headers: { ...corsHeaders, "Content-Type": "application/json" },
280→    });
281→  }
282→});
