 11→import { exportToCSV } from "@/lib/csvExport";
 12→
 13→const PAGE_SIZE = 20;
 14→
 15→const PaymentsTab = () => {
 16→  const [page, setPage] = useState(0);
 17→
 18→  // Fetch user email map for display
 19→  const { data: userMap } = useQuery({
 20→    queryKey: ["admin_users"],
 21→    queryFn: async () => {
 22→      const { data, error } = await supabase.functions.invoke("admin-users", { method: "GET" });
 23→      if (error) throw error;
 24→      const map: Record<string, string> = {};
 25→      (data as any[])?.forEach((u) => { map[u.id] = u.email; });
 26→      return map;
 27→    },
 28→    staleTime: 5 * 60 * 1000,
 29→  });
 30→
 31→  const { data, isLoading } = useQuery({
 32→    queryKey: ["admin_payments", page],
 33→    queryFn: async () => {
 34→      const from = page * PAGE_SIZE;
 35→      const to = from + PAGE_SIZE - 1;
 36→      const { data, error, count } = await supabase
 37→        .from("payments")
 38→        .select("*", { count: "exact" })
 39→        .order("created_at", { ascending: false })
 40→        .range(from, to);
 41→      if (error) throw error;
 42→      return { payments: data, total: count ?? 0 };
 43→    },
 44→  });
 45→
 46→  const totalPages = Math.ceil((data?.total ?? 0) / PAGE_SIZE);
 47→
 48→  const statusVariant = (status: string) => {
 49→    switch (status) {
 50→      case "paid": return "success" as const;
 51→      case "created": return "warning" as const;
 52→      case "failed": return "destructive" as const;
 53→      default: return "secondary" as const;
 54→    }
 55→  };
 56→
 57→  const statusLabel = (status: string) => {
 58→    switch (status) {
 59→      case "paid": return "Successful";
 60→      case "created": return "Unpaid";
 61→      case "failed": return "Failed";
 62→      case "dismissed": return "Cancelled";
 63→      default: return "Pending";
 64→    }
 65→  };
 66→
 67→  const handleExport = () => {
 68→    if (!data?.payments?.length) return;
 69→    const rows = data.payments.map((p: any) => ({
 70→      order_id: p.razorpay_order_id || "",
 71→      user_email: userMap?.[p.user_id] || p.user_id,
 72→      amount: `${p.currency} ${(p.amount / 100).toFixed(2)}`,
 73→      credits: p.credits_purchased,
 74→      status: statusLabel(p.status),
 75→      date: new Date(p.created_at).toISOString(),
 76→    }));
 77→    exportToCSV(rows, "payments");
 78→  };
 79→
 80→  return (
 81→    <div className="space-y-6">
 82→      <div className="flex items-center justify-between">
 83→        <h2 className="text-xl font-semibold flex items-center gap-2">
 84→          <CreditCard className="h-5 w-5 text-primary" />
 85→          Payments
 86→        </h2>
 87→        <Button variant="outline" size="sm" onClick={handleExport} disabled={!data?.payments?.length}>
 88→          <Download className="h-4 w-4 mr-1" />CSV
 89→        </Button>
 90→      </div>
 91→      {isLoading ? (
 92→        <div className="space-y-2">
 93→          {[...Array(5)].map((_, i) => (
 94→            <Skeleton key={i} className="h-12 w-full" />
 95→          ))}
 96→        </div>
 97→      ) : (
 98→        <div className="rounded-md border">
 99→           <Table>
100→            <TableHeader>
101→              <TableRow>
102→                <TableHead>Order ID</TableHead>
103→                <TableHead>User</TableHead>
104→                <TableHead>Amount</TableHead>
105→                <TableHead>Credits</TableHead>
106→                <TableHead>Gateway</TableHead>
107→                <TableHead>Status</TableHead>
108→                <TableHead>Date</TableHead>
109→              </TableRow>
110→            </TableHeader>
111→            <TableBody>
112→              {data?.payments?.length === 0 && (
113→                 <TableRow>
114→                   <TableCell colSpan={7} className="text-center text-muted-foreground py-8">
115→                     No payments recorded yet.
116→                   </TableCell>
117→                 </TableRow>
118→              )}
119→              {data?.payments?.map((p: any) => (
120→                <TableRow key={p.id}>
121→                  <TableCell className="font-mono text-xs">
122→                    {(p as any).dodo_payment_id || p.razorpay_order_id || "—"}
123→                  </TableCell>
124→                  <TableCell className="text-sm max-w-[200px] truncate" title={userMap?.[p.user_id] || p.user_id}>
125→                    {userMap?.[p.user_id] || p.user_id?.slice(0, 8) + "…"}
126→                  </TableCell>
127→                  <TableCell>
128→                    {p.currency} {(p.amount / 100).toFixed(2)}
129→                  </TableCell>
130→                  <TableCell>{p.credits_purchased}</TableCell>
131→                  <TableCell>
132→                    <Badge variant="outline" className="text-[10px]">
133→                      {(p as any).payment_gateway === "dodo" ? "Dodo" : "Razorpay"}
134→                    </Badge>
135→                  </TableCell>
136→                  <TableCell>
137→                    <Badge variant={statusVariant(p.status)}>
138→                      {statusLabel(p.status)}
139→                    </Badge>
140→                  </TableCell>
141→                  <TableCell className="text-sm text-muted-foreground">
142→                    {new Date(p.created_at).toLocaleDateString("en-US", {
143→                      month: "short", day: "numeric", year: "numeric",
144→                      hour: "2-digit", minute: "2-digit",
145→                    })}
146→                  </TableCell>
147→                </TableRow>
148→              ))}
149→            </TableBody>
150→          </Table>
151→          {totalPages > 1 && (
152→            <div className="flex items-center justify-between px-4 py-3 border-t border-border">
153→              <span className="text-sm text-muted-foreground">Page {page + 1} of {totalPages}</span>
154→              <div className="flex items-center gap-2">
155→                <Button variant="outline" size="icon" className="h-7 w-7" disabled={page === 0} onClick={() => setPage(p => p - 1)}>
156→                  <ChevronLeft className="h-3.5 w-3.5" />
157→                </Button>
158→                <Button variant="outline" size="icon" className="h-7 w-7" disabled={page >= totalPages - 1} onClick={() => setPage(p => p + 1)}>
159→                  <ChevronRight className="h-3.5 w-3.5" />
160→                </Button>
161→              </div>
162→            </div>
163→          )}
164→        </div>
165→      )}
166→    </div>
167→  );
168→};
169→
170→export default PaymentsTab;
