 6→    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
 7→};
 8→
 9→Deno.serve(async (req) => {
10→  if (req.method === "OPTIONS") {
11→    return new Response(null, { headers: corsHeaders });
12→  }
13→
14→  try {
15→    const authHeader = req.headers.get("Authorization");
16→    if (!authHeader?.startsWith("Bearer ")) {
17→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
18→        status: 401,
19→        headers: { ...corsHeaders, "Content-Type": "application/json" },
20→      });
21→    }
22→
23→    const supabase = createClient(
24→      Deno.env.get("SUPABASE_URL")!,
25→      Deno.env.get("SUPABASE_ANON_KEY")!,
26→      { global: { headers: { Authorization: authHeader } } }
27→    );
28→
29→    const token = authHeader.replace("Bearer ", "");
30→    const { data: claimsData, error: claimsError } = await supabase.auth.getClaims(token);
31→    if (claimsError || !claimsData?.claims) {
32→      return new Response(JSON.stringify({ error: "Unauthorized" }), {
33→        status: 401,
34→        headers: { ...corsHeaders, "Content-Type": "application/json" },
35→      });
36→    }
37→    const userId = claimsData.claims.sub;
38→
39→    const serviceClient = createClient(
40→      Deno.env.get("SUPABASE_URL")!,
41→      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
42→    );
43→
44→    // Get user's active subscription
45→    const { data: profile } = await serviceClient
46→      .from("profiles")
47→      .select("razorpay_subscription_id, plan")
48→      .eq("user_id", userId)
49→      .single();
50→
51→    if (!profile?.razorpay_subscription_id) {
52→      return new Response(JSON.stringify({ error: "No active subscription found" }), {
53→        status: 400,
54→        headers: { ...corsHeaders, "Content-Type": "application/json" },
55→      });
56→    }
57→
58→    const razorpayKeyId = Deno.env.get("RAZORPAY_KEY_ID")!;
59→    const razorpayKeySecret = Deno.env.get("RAZORPAY_KEY_SECRET")!;
60→
61→    // Cancel subscription at end of billing cycle
62→    const razorpayRes = await fetch(
63→      `https://api.razorpay.com/v1/subscriptions/${profile.razorpay_subscription_id}/cancel`,
64→      {
65→        method: "POST",
66→        headers: {
67→          "Content-Type": "application/json",
68→          Authorization: "Basic " + btoa(`${razorpayKeyId}:${razorpayKeySecret}`),
69→        },
70→        body: JSON.stringify({ cancel_at_cycle_end: 1 }),
71→      }
72→    );
73→
74→    const result = await razorpayRes.json();
75→    if (!razorpayRes.ok) {
76→      console.error("Razorpay cancel error:", result);
77→      return new Response(JSON.stringify({ error: "Failed to cancel subscription", details: result }), {
78→        status: 500,
79→        headers: { ...corsHeaders, "Content-Type": "application/json" },
80→      });
81→    }
82→
83→    return new Response(
84→      JSON.stringify({ status: "cancellation_scheduled", ends_at: result.ended_at || result.current_end }),
85→      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
86→    );
87→  } catch (err: unknown) {
88→    console.error("Error:", err);
89→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
90→      status: 500,
91→      headers: { ...corsHeaders, "Content-Type": "application/json" },
