 17→const CreditPacksTab = () => {
 18→  const qc = useQueryClient();
 19→  const [saving, setSaving] = useState(false);
 20→  const [deleteTarget, setDeleteTarget] = useState<{ id: string; name: string } | null>(null);
 21→
 22→  const { data: packs } = useQuery({
 23→    queryKey: ["admin_credit_packs"],
 24→    queryFn: async () => {
 25→      const { data, error } = await supabase.from("credit_packs").select("*").order("created_at");
 26→      if (error) throw error;
 27→      return data;
 28→    },
 29→  });
 30→
 31→  const [editPack, setEditPack] = useState<any>(null);
 32→  const [form, setForm] = useState({ name: "", price: "", credits: "", active: true, is_trial: false, dodo_product_id: "" });
 33→
 34→  const openNew = () => { setForm({ name: "", price: "", credits: "", active: true, is_trial: false, dodo_product_id: "" }); setEditPack("new"); };
 35→  const openEdit = (p: any) => { setForm({ name: p.name, price: String(p.price), credits: String(p.credits), active: p.active, is_trial: p.is_trial ?? false, dodo_product_id: (p as any).dodo_product_id || "" }); setEditPack(p); };
 36→
 37→  const validate = () => {
 38→    if (!form.name.trim()) { toast.error("Pack name is required"); return false; }
 39→    if (!form.price || parseFloat(form.price) < 0) { toast.error("Price must be 0 or greater"); return false; }
 40→    if (!form.credits || parseInt(form.credits) <= 0) { toast.error("Credits must be greater than 0"); return false; }
 41→    // Only one active trial pack allowed
 42→    if (form.is_trial && form.active) {
 43→      const existingTrial = packs?.find((p: any) => p.is_trial && p.active && (editPack === "new" || p.id !== editPack?.id));
 44→      if (existingTrial) { toast.error("Only one active trial pack is allowed. Deactivate the existing one first."); return false; }
 45→    }
 46→    return true;
 47→  };
 48→
 49→  const save = async () => {
 50→    if (!validate()) return;
 51→    setSaving(true);
 52→    try {
 53→      const payload = { name: form.name.trim(), price: parseFloat(form.price), credits: parseInt(form.credits), active: form.active, is_trial: form.is_trial, dodo_product_id: form.dodo_product_id.trim() || null } as any;
 54→      if (editPack === "new") {
 55→        const { error } = await supabase.from("credit_packs").insert(payload);
 56→        if (error) { toast.error(error.message); return; }
 57→      } else {
 58→        const { error } = await supabase.from("credit_packs").update(payload).eq("id", editPack.id);
 59→        if (error) { toast.error(error.message); return; }
 60→      }
 61→      toast.success("Credit pack saved");
 62→      logAuditAction(
 63→        editPack === "new" ? "credit_pack.create" : "credit_pack.update",
 64→        "credit_pack",
 65→        editPack === "new" ? undefined : editPack.id,
 66→        { name: form.name, price: form.price, credits: form.credits, is_trial: form.is_trial },
 67→      );
 68→      qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
 69→      setEditPack(null);
 70→    } finally {
 71→      setSaving(false);
 72→    }
 73→  };
 74→
 75→  const confirmDelete = async () => {
 76→    if (!deleteTarget) return;
 77→    const { error } = await supabase.from("credit_packs").delete().eq("id", deleteTarget.id);
 78→    if (error) { toast.error(error.message); return; }
 79→    toast.success("Credit pack deleted");
 80→    logAuditAction("credit_pack.delete", "credit_pack", deleteTarget.id, { name: deleteTarget.name });
 81→    qc.invalidateQueries({ queryKey: ["admin_credit_packs"] });
 82→    setDeleteTarget(null);
 83→  };
 84→
 85→  return (
 86→    <>
 87→      <Card>
