 93→            </DialogTrigger>
 94→            <DialogContent>
 95→              <DialogHeader><DialogTitle>{editPack === "new" ? "New Credit Pack" : "Edit Credit Pack"}</DialogTitle></DialogHeader>
 96→              <div className="space-y-3">
 97→                <div><Label>Name</Label><Input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="e.g. Starter Pack" /></div>
 98→                <div className="grid grid-cols-2 gap-3">
 99→                  <div><Label>Price ($)</Label><Input type="number" min="0" step="0.01" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} /></div>
100→                  <div><Label>Credits</Label><Input type="number" min="1" value={form.credits} onChange={(e) => setForm({ ...form, credits: e.target.value })} /></div>
101→                </div>
102→                <div className="flex items-center gap-2"><Switch checked={form.active} onCheckedChange={(c) => setForm({ ...form, active: c })} /><Label>Active</Label></div>
103→                <div className="flex items-center gap-2">
104→                  <Switch checked={form.is_trial} onCheckedChange={(c) => setForm({ ...form, is_trial: c })} />
105→                  <Label className="flex items-center gap-1.5">
106→                    <Gift className="h-3.5 w-3.5 text-amber-500" />
107→                    Trial Pack
108→                  </Label>
109→                </div>
110→                {form.is_trial && (
111→                  <p className="text-xs text-muted-foreground bg-amber-500/10 rounded-md px-3 py-2">
112→                    Trial packs are only visible to users who haven't made any purchase yet. Only one active trial pack is allowed.
113→                  </p>
114→                )}
115→                <div><Label>Dodo Product ID</Label><Input value={form.dodo_product_id} onChange={(e) => setForm({ ...form, dodo_product_id: e.target.value })} placeholder="pdt_..." /></div>
116→                <Button onClick={save} className="w-full" disabled={saving}>
117→                  {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
118→                  Save
119→                </Button>
120→              </div>
121→            </DialogContent>
122→          </Dialog>
123→        </CardHeader>
124→        <CardContent className="p-0">
125→          <Table>
126→            <TableHeader><TableRow><TableHead>Name</TableHead><TableHead>Price</TableHead><TableHead>Credits</TableHead><TableHead>Type</TableHead><TableHead>Dodo</TableHead><TableHead>Active</TableHead><TableHead></TableHead></TableRow></TableHeader>
127→            <TableBody>
128→              {packs?.map((p: any) => (
129→                <TableRow key={p.id}>
130→                  <TableCell className="font-medium">{p.name}</TableCell>
131→                  <TableCell>${p.price}</TableCell>
