152→                    <Button variant="ghost" size="icon" onClick={() => setDeleteTarget({ id: p.id, name: p.name })}><Trash2 className="h-3.5 w-3.5 text-destructive" /></Button>
153→                  </TableCell>
154→                </TableRow>
155→              ))}
156→            </TableBody>
157→          </Table>
158→        </CardContent>
159→      </Card>
160→
161→      <ConfirmDialog
162→        open={deleteTarget !== null}
