  2→import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
  3→
  4→const corsHeaders = {
  5→  "Access-Control-Allow-Origin": "*",
  6→  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, webhook-id, webhook-signature, webhook-timestamp",
  7→};
